<?php
require_once __DIR__.'/includes/bootstrap.php';
require_role(['admin']);
$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){
    verify_csrf(); $action=$_POST['action']??'';
    if($action==='add_department'){
        $name=trim($_POST['department_name']??'');
        if($name==='') $msg='Enter a department name.';
        else { try{$s=$pdo->prepare('INSERT INTO departments(name) VALUES(?)');$s->execute([$name]);flash('success','Department created successfully.');redirect('course_management.php');}catch(PDOException $e){$msg='Department already exists or could not be created.';} }
    } elseif($action==='add_course'){
        $deptId=(int)($_POST['department_id']??0);$code=trim($_POST['course_code']??'');$title=trim($_POST['course_title']??'');$description=trim($_POST['description']??'');
        $s=$pdo->prepare('SELECT id FROM departments WHERE id=? AND is_active=1');$s->execute([$deptId]);
        if(!$s->fetch()||$code===''||$title==='') $msg='Choose a department and enter both course code and course title.';
        else {try{$s=$pdo->prepare('INSERT INTO courses(department_id,course_code,course_title,description) VALUES(?,?,?,?)');$s->execute([$deptId,$code,$title,$description?:null]);flash('success','Course created and assigned to its department. Eligible users can now select it in evaluation forms.');redirect('course_management.php');}catch(PDOException $e){$msg='Course code already exists in this department, or the course could not be saved.';}}
    } elseif($action==='toggle_course'){
        $id=(int)($_POST['course_id']??0);$s=$pdo->prepare('UPDATE courses SET is_active=IF(is_active=1,0,1) WHERE id=?');$s->execute([$id]);flash('success','Course status updated.');redirect('course_management.php');
    } elseif($action==='assign_evaluation'){
        $userId=(int)($_POST['evaluator_user_id']??0);$courseId=(int)($_POST['course_id']??0);$instructorId=(int)($_POST['instructor_id']??0);
        $starts=str_replace('T',' ',trim($_POST['starts_at']??''));$deadline=str_replace('T',' ',trim($_POST['deadline_at']??''));
        $u=$pdo->prepare("SELECT id,role FROM users WHERE id=? AND is_active=1 AND role IN ('student','department_head','peer','self')");$u->execute([$userId]);$target=$u->fetch();
        $c=$pdo->prepare('SELECT c.id,d.name AS department_name FROM courses c JOIN departments d ON d.id=c.department_id WHERE c.id=? AND c.is_active=1 AND d.is_active=1');$c->execute([$courseId]);$courseTarget=$c->fetch();
        $i=$pdo->prepare('SELECT id,full_name,department FROM instructors WHERE id=? AND is_active=1');$i->execute([$instructorId]);$instructorTarget=$i->fetch();
        if(!$target||!$courseTarget||!$instructorTarget||!$starts||!$deadline||strtotime($deadline)<=strtotime($starts))$msg='Choose an active evaluator, course, instructor, and valid start/deadline range.';
        elseif(strcasecmp(trim($courseTarget['department_name']),trim($instructorTarget['department']))!==0)$msg='The instructor and course must belong to the same department.';
        elseif($target['role']==='self'&&(int)($pdo->query('SELECT instructor_id FROM users WHERE id='.(int)$userId)->fetchColumn())!==$instructorId)$msg='For self-evaluation, the selected instructor must match the instructor profile linked to that account.';
        else {try{$s=$pdo->prepare('INSERT INTO evaluation_assignments(evaluator_user_id,course_id,instructor_id,evaluator_type,starts_at,deadline_at,created_by) VALUES(?,?,?,?,?,?,?)');$s->execute([$userId,$courseId,$instructorId,$target['role'],$starts,$deadline,(int)current_user()['id']]);flash('success','Course assigned with its own evaluation time window.');redirect('course_management.php');}catch(PDOException $e){$msg='Could not create assignment. Check the selected user, course, and database migration.';}}
    } elseif($action==='toggle_assignment'){
        $id=(int)($_POST['assignment_id']??0);$s=$pdo->prepare('UPDATE evaluation_assignments SET is_active=IF(is_active=1,0,1) WHERE id=?');$s->execute([$id]);flash('success','Evaluation assignment status updated.');redirect('course_management.php');
    } elseif($action==='toggle_department'){
        $id=(int)($_POST['department_id']??0);$s=$pdo->prepare('UPDATE departments SET is_active=IF(is_active=1,0,1) WHERE id=?');$s->execute([$id]);flash('success','Department status updated.');redirect('course_management.php');
    }
}
$departments=$pdo->query('SELECT d.*,COUNT(c.id) course_count FROM departments d LEFT JOIN courses c ON c.department_id=d.id GROUP BY d.id ORDER BY d.name')->fetchAll();
$courses=$pdo->query('SELECT c.*,d.name department_name FROM courses c JOIN departments d ON d.id=c.department_id WHERE c.is_active=1 AND d.is_active=1 ORDER BY d.name,c.course_code')->fetchAll();
$evaluators=$pdo->query("SELECT id,full_name,username,role,department FROM users WHERE is_active=1 AND role IN ('student','department_head','peer','self') ORDER BY full_name")->fetchAll();
$assignments=$pdo->query('SELECT a.*,u.full_name,u.username,u.role,c.course_code,c.course_title,d.name department_name,i.full_name AS target_instructor_name FROM evaluation_assignments a JOIN users u ON u.id=a.evaluator_user_id JOIN courses c ON c.id=a.course_id JOIN departments d ON d.id=c.department_id JOIN instructors i ON i.id=a.instructor_id ORDER BY a.created_at DESC')->fetchAll();
page_header('Course & department management');show_flash();
?><div class="page-intro"><div><div class="eyebrow">ACADEMIC STRUCTURE</div><h1>Course &amp; department management</h1><p>Create departments and courses, then assign each evaluator only the courses they are authorized to evaluate, with a specific start time and deadline.</p></div><div class="actions"><a class="btn secondary" href="<?=BASE_URL?>/course_catalog.php">▦ View courses by department</a><a class="btn secondary" href="<?=BASE_URL?>/users.php">♙ User Accounts</a></div></div>
<?php if($msg):?><div class="alert error"><?=e($msg)?></div><?php endif;?>
<div class="two-col"><section class="panel"><h2>1. Create department</h2><form method="post" class="form-grid"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add_department"><label class="wide">Department name<input name="department_name" placeholder="e.g. Computer Science" required></label><div><button class="btn primary">＋ Create department</button></div></form></section>
<section class="panel"><h2>2. Create course</h2><form method="post" class="form-grid"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add_course"><label>Department<select name="department_id" required><option value="">Select department</option><?php foreach($departments as $d):if($d['is_active']):?><option value="<?=$d['id']?>"><?=e($d['name'])?></option><?php endif;endforeach;?></select></label><label>Course code<input name="course_code" placeholder="e.g. CS301" required></label><label class="wide">Course title<input name="course_title" placeholder="e.g. Web Programming" required></label><label class="wide">Description (optional)<textarea name="description" rows="2"></textarea></label><div><button class="btn primary" <?=!array_filter($departments,fn($d)=>$d['is_active'])?'disabled':''?>>＋ Create course</button></div></form></section></div>
<section class="panel"><div class="section-head"><div><h2>3. Assign course and evaluation period</h2><p class="muted">Only the selected evaluator can evaluate the selected course during the assigned period.</p></div></div><form method="post" class="form-grid"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="assign_evaluation"><label>Evaluator account<select name="evaluator_user_id" required><option value="">Select evaluator</option><?php foreach($evaluators as $ev):?><option value="<?=$ev['id']?>"><?=e($ev['full_name'].' ('.$ev['username'].') — '.(roles()[$ev['role']]??$ev['role']))?></option><?php endforeach;?></select></label><label>Course<select name="course_id" required><option value="">Select course</option><?php foreach($courses as $c):?><option value="<?=$c['id']?>"><?=e($c['course_code'].' — '.$c['course_title'].' ('.$c['department_name'].')')?></option><?php endforeach;?></select></label><label>Instructor being evaluated<select name="instructor_id" required><option value="">Select instructor</option><?php foreach($pdo->query("SELECT id,full_name,department FROM instructors WHERE is_active=1 ORDER BY full_name")->fetchAll() as $ins):?><option value="<?=$ins['id']?>"><?=e($ins['full_name'].' — '.$ins['department'])?></option><?php endforeach;?></select></label><label>Starts at<input type="datetime-local" name="starts_at" required></label><label>Deadline<input type="datetime-local" name="deadline_at" required></label><div class="wide"><button class="btn primary" <?=(!$evaluators||!$courses)?'disabled':''?>>＋ Assign evaluation</button></div></form></section>
<section class="panel table-wrap"><div class="section-head"><div><h2>Evaluation assignments</h2><p class="muted">This is the assignment list, not a duplicate course registry. Use “Courses by department” to browse all courses.</p></div><span class="count-pill"><?=count($assignments)?> assignments</span></div><table><thead><tr><th>Evaluator</th><th>Role</th><th>Course / department</th><th>Instructor being evaluated</th><th>Start</th><th>Deadline</th><th>Status</th><th>Action</th></tr></thead><tbody><?php if(!$assignments):?><tr><td colspan="8">No evaluation assignments yet.</td></tr><?php else:foreach($assignments as $a):?><tr><td><?=e($a['full_name'])?><br><small class="muted">@<?=e($a['username'])?></small></td><td><?=e(roles()[$a['role']]??$a['role'])?></td><td><b><?=e($a['course_code'].' — '.$a['course_title'])?></b><br><small class="muted"><?=e($a['department_name'])?></small></td><td><?=e($a['target_instructor_name'])?></td><td><?=e(date('M j, Y g:i A',strtotime($a['starts_at'])))?></td><td><?=e(date('M j, Y g:i A',strtotime($a['deadline_at'])))?></td><td><?=$a['is_active']?'Active':'Inactive'?></td><td><form method="post" onsubmit="return confirm('Change this assignment status?')"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="toggle_assignment"><input type="hidden" name="assignment_id" value="<?=$a['id']?>"><button class="btn small secondary"><?=$a['is_active']?'Deactivate':'Activate'?></button></form></td></tr><?php endforeach;endif;?></tbody></table></section>
<?php page_footer();?>
